#!/usr/bin/env python3
"""
init_config.py - Helper script to initialize rts.config.yml and service-map.yml for a repository.

Can run interactively or flag-driven via CLI.
Standard library only (Python 3.9+).
"""

import argparse
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any, Dict, List, Optional, Set


def detect_git_remote() -> Optional[str]:
    """Tries to detect git remote origin URL of current repository."""
    try:
        res = subprocess.run(
            ["git", "config", "--get", "remote.origin.url"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        if res.returncode == 0 and res.stdout.strip():
            return res.stdout.strip()
    except Exception:
        pass
    return None


def detect_recent_jira_prefixes(count: int = 50) -> List[str]:
    """Scans recent git commit logs to find prevalent Jira ticket prefixes."""
    prefixes: Set[str] = set()
    try:
        res = subprocess.run(
            ["git", "log", f"-n{count}", "--pretty=%s"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        if res.returncode == 0:
            for match in re.finditer(r'\b([A-Z]{2,10})-\d+\b', res.stdout):
                prefixes.add(match.group(1))
    except Exception:
        pass
    return sorted(list(prefixes))


def generate_default_config(
    automation_repo: str,
    framework: str = "auto",
    branch: str = "main",
    service_map_path: str = "./service-map.yml"
) -> str:
    """Generates standard rts.config.yml content."""
    return f"""# RTS Configuration - Regression Test Selector
# Auto-generated by init_config.py

# Automation repository location (git URL or local path)
# Supports github.com, *.ghe.com (EU data residency), and GHES
automation_repo: {automation_repo}
branch: {branch}

# Test framework in the automation repo: auto | playwright-ts | selenium-java
framework: {framework}

# Test metadata source adapter: repo-only | xray | browserstack
test_source: repo-only

# Suite identification tags
regression_suite:
  tag: "@regression"

smoke_suite:
  tag: "@smoke"

# Service to test tag/directory map
service_map: {service_map_path}

# Always-run rules (e.g. run smoke when auth files change)
always_run:
  - when_changed: "src/auth/**"
    run_tag: "@smoke"
  - when_changed: "**/migrations/**"
    run_tag: "@smoke"

# Critical files that trigger risk widening
risk_paths:
  - "**/migrations/**"
  - "**/auth/**"
  - "**/security/**"
  - "pom.xml"
  - "package.json"
  - "build.gradle"
  - "requirements.txt"

# CLI template for executing selected tests
run_command_template: "npx playwright test --grep \\"{{grep}}\\""
"""


def generate_service_map(repo_name: str, jira_prefixes: List[str]) -> str:
    """Generates a starter service-map.yml content."""
    prefixes_formatted = "\n".join([f'      - "{p}"' for p in (jira_prefixes or ["PAY", "PSP"])])
    return f"""# Service to Automation Test Mapping
# Map developer components to test tags, folders, and Jira project keys

services:
  {repo_name}:
    jira_prefixes:
{prefixes_formatted}
    test_tags:
      - "@{repo_name.replace('-service', '')}"
      - "@regression"
    test_folders:
      - "tests/{repo_name.replace('-service', '')}/**"
"""


def main():
    parser = argparse.ArgumentParser(description="Initialize rts.config.yml and service-map.yml for a project.")
    parser.add_argument("--automation-repo", type=str, help="Automation repo URL or local path.")
    parser.add_argument("--framework", type=str, default="auto", choices=["auto", "playwright-ts", "selenium-java"], help="Test framework.")
    parser.add_argument("--branch", type=str, default="main", help="Automation repo branch (default: main).")
    parser.add_argument("--output-config", type=str, default="rts.config.yml", help="Output path for rts.config.yml.")
    parser.add_argument("--output-service-map", type=str, default="service-map.yml", help="Output path for service-map.yml.")
    parser.add_argument("--non-interactive", action="store_true", help="Run without interactive prompts.")

    args = parser.parse_args()

    current_dir_name = Path(os.getcwd()).name
    detected_remote = detect_git_remote()
    detected_jira = detect_recent_jira_prefixes()

    automation_repo = args.automation_repo
    if not automation_repo:
        if args.non_interactive:
            automation_repo = "../automation-tests"
        else:
            sys.stdout.write(f"Detected project: {current_dir_name}\n")
            if detected_remote:
                sys.stdout.write(f"Current git origin: {detected_remote}\n")
            if detected_jira:
                sys.stdout.write(f"Detected Jira project keys: {', '.join(detected_jira)}\n")
            try:
                user_input = input("Enter automation repo URL or relative path [../automation-tests]: ").strip()
                automation_repo = user_input if user_input else "../automation-tests"
            except (EOFError, KeyboardInterrupt):
                automation_repo = "../automation-tests"

    config_content = generate_default_config(
        automation_repo=automation_repo,
        framework=args.framework,
        branch=args.branch,
        service_map_path=f"./{Path(args.output_service_map).name}"
    )

    service_map_content = generate_service_map(
        repo_name=current_dir_name,
        jira_prefixes=detected_jira
    )

    with open(args.output_config, "w", encoding="utf-8") as f:
        f.write(config_content)
    sys.stderr.write(f"Generated {args.output_config}\n")

    with open(args.output_service_map, "w", encoding="utf-8") as f:
        f.write(service_map_content)
    sys.stderr.write(f"Generated {args.output_service_map}\n")

    sys.stderr.write("\nInitialization complete! Review and commit rts.config.yml and service-map.yml.\n")


if __name__ == "__main__":
    main()
